package studio.jiayu.neoagent;

import java.util.*;

public final class ContainerLabelProofTest {
 static int checks;static final int V=ContainerLabelProof.VISIBLE|ContainerLabelProof.ENABLED;
 static void yes(boolean condition,String why){checks++;if(!condition)throw new AssertionError(why);}
 static ContainerLabelProof.Node node(int depth,int children,String role,int flags,String text,String desc,int top){return new ContainerLabelProof.Node(depth,children,3,"fixture.app",role,"","",0,top,1080,top+120,flags,0,0,0,text,desc,"","","16:0:;");}
 static ContainerLabelProof.Proof row(String title,String artist){ContainerLabelProof.Builder b=new ContainerLabelProof.Builder();b.begin(node(0,2,"ViewGroup",V|ContainerLabelProof.CLICKABLE,"","",500));b.begin(node(1,0,"TextView",V,title,"",500));b.end();b.begin(node(1,0,"TextView",V,artist,"",560));b.end();b.end();return b.finish();}
 static ContainerLabelProof.Proof mixed(String independent,int count){ContainerLabelProof.Builder b=new ContainerLabelProof.Builder();b.begin(node(0,count,"ViewGroup",V|ContainerLabelProof.CLICKABLE,"","",500));b.begin(node(1,0,"TextView",V,"parent label","",500));b.end();for(int i=1;i<count;i++){b.begin(node(1,1,"Button",V|ContainerLabelProof.CLICKABLE,"","",560+i));b.begin(node(2,0,"TextView",V,independent,"",560+i));b.end();b.end();}b.end();return b.finish();}
 static ContainerLabelProof.Proof change(int field){ContainerLabelProof.Builder b=new ContainerLabelProof.Builder();b.begin(node(0,1,"ViewGroup",V|ContainerLabelProof.CLICKABLE,"","",500));ContainerLabelProof.Node n=new ContainerLabelProof.Node(1,0,field==0?4:3,field==1?"other.app":"fixture.app",field==2?"Button":"TextView",field==3?"new_id":"",field==4?"different_unique_id":"",field==5?1:0,field==6?501:500,field==7?1079:1080,field==8?621:620,field==9?V|ContainerLabelProof.SELECTED:V,field==10?1:0,field==11?1:0,field==12?1:0,"same title",field==13?"new description":"",field==14?"new hint":"",field==15?"new state":"",field==16?"32:0:;":"16:0:;");b.begin(n);b.end();b.end();return b.finish();}
 public static void main(String[] args){
  ContainerLabelProof.Proof original=row("有何不可","许嵩·自定义 2700w+");yes(original!=null&&original.nodes==3,"derived label row lacks complete proof");yes(original.same(row("有何不可","许嵩·自定义 2700w+")),"unchanged target rejected");yes(!original.same(row("有何不可","其他歌手·自定义 2700w+")),"artist replacement allowed");yes(!original.same(row("其他歌曲","许嵩·自定义 2700w+")),"title replacement allowed");yes(!original.same(row("许嵩·自定义 2700w+","有何不可")),"reordered children allowed");
  String longLabel=String.join("",Collections.nCopies(300,"甲"));yes(!row(longLabel+"尾A","artist").same(row(longLabel+"尾B","artist")),"label tail beyond display truncation ignored");yes(!row(longLabel+"尾A","artist").same(row(longLabel+"尾A ","artist")),"full label whitespace discarded");
  for(int field=0;field<=16;field++)yes(!change(-1).same(change(field)),"native role/layout/action field ignored "+field);
  ContainerLabelProof.Builder b=new ContainerLabelProof.Builder();b.begin(node(0,2,"ViewGroup",V|ContainerLabelProof.CLICKABLE,"","",0));b.begin(node(1,0,"TextView",V,"song","",0));b.end();yes(!b.end()&&b.finish()==null,"missing child accepted");
  b=new ContainerLabelProof.Builder();b.begin(node(0,0,"ViewGroup",V|ContainerLabelProof.CLICKABLE,"","",0));yes(!b.begin(node(1,0,"TextView",V,"extra","",0))&&b.finish()==null,"undeclared child accepted");
  b=new ContainerLabelProof.Builder();b.begin(node(0,1,"ViewGroup",V|ContainerLabelProof.CLICKABLE,"","",0));yes(!b.begin(node(2,0,"TextView",V,"wrong depth","",0))&&b.finish()==null,"skipped hierarchy level accepted");
  b=new ContainerLabelProof.Builder();b.begin(node(0,1,"ViewGroup",V|ContainerLabelProof.CLICKABLE,"","",0));b.incomplete();yes(b.finish()==null,"null child/read failure accepted");
  b=new ContainerLabelProof.Builder();for(int depth=0;depth<=ContainerLabelProof.MAX_DEPTH+1;depth++)if(!b.begin(node(depth,1,"ViewGroup",V,"label","",0)))break;yes(b.finish()==null,"depth truncation accepted");
  b=new ContainerLabelProof.Builder();b.begin(node(0,ContainerLabelProof.MAX_NODES,"ViewGroup",V|ContainerLabelProof.CLICKABLE,"","",0));for(int i=0;i<ContainerLabelProof.MAX_NODES;i++){if(!b.begin(node(1,0,"TextView",V,"label","",i)))break;b.end();}yes(b.finish()==null,"node-budget truncation accepted");
  yes(row(String.join("",Collections.nCopies(ContainerLabelProof.MAX_CHARACTERS,"x")),"artist")==null,"character-budget truncation accepted");
  b=new ContainerLabelProof.Builder();b.begin(node(0,1,"ViewGroup",V|ContainerLabelProof.CLICKABLE,"","",0));b.begin(node(1,0,"Button",V|ContainerLabelProof.CLICKABLE,"independent button","",0));b.end();b.end();yes(b.finish()==null,"independent clickable child supplied parent semantics");
  for(int flags:new int[]{ContainerLabelProof.EDITABLE,ContainerLabelProof.LONG_CLICKABLE}){b=new ContainerLabelProof.Builder();b.begin(node(0,1,"ViewGroup",V|ContainerLabelProof.CLICKABLE,"","",0));b.begin(node(1,1,"Container",V|flags,"","",0));b.begin(node(2,0,"TextView",V,"independent descendant label","",0));b.end();b.end();b.end();yes(b.finish()==null,"independent interactive subtree supplied parent semantics");}
  b=new ContainerLabelProof.Builder();b.begin(node(0,1,"ViewGroup",V|ContainerLabelProof.CLICKABLE,"","",0));b.begin(node(1,0,"TextView",ContainerLabelProof.ENABLED,"hidden label","",0));b.end();b.end();yes(b.finish()==null,"invisible label supplied parent semantics");
  b=new ContainerLabelProof.Builder();b.begin(node(0,1,"ViewGroup",V|ContainerLabelProof.CLICKABLE,"","",0));yes(!b.begin(node(1,0,"EditText",V|ContainerLabelProof.PASSWORD,"private","",0))&&b.finish()==null,"password subtree supplied proof");
  yes(!row("a|b","c").same(row("a","b|c")),"field delimiter collision");
  yes(!row("标签","artist").same(row("标签标签","artist")),"UTF-8 label change ignored");
  yes(!row(String.valueOf((char)0xd800),"artist").same(row(String.valueOf((char)0xd801),"artist")),"unpaired surrogate replacement merged distinct full labels");
  String spaces=String.join("",Collections.nCopies(300," "));yes(!row(spaces,"artist").same(row(spaces+"tail","artist")),"own-label-style whitespace prefix hid a changed full tail");
  yes(mixed("independent A",2)!=null,"independent child suppressed a separate valid parent label");yes(!mixed("independent A",2).same(mixed("independent B",2)),"independent interactive subtree omitted from full fingerprint");yes(!mixed("independent A",2).same(mixed("independent A",3)),"added independent subtree ignored");
  b=new ContainerLabelProof.Builder();for(int depth=0;depth<=ContainerLabelProof.MAX_DEPTH;depth++)b.begin(node(depth,depth==ContainerLabelProof.MAX_DEPTH?0:1,"Container",V|(depth==0?ContainerLabelProof.CLICKABLE:0),depth==ContainerLabelProof.MAX_DEPTH?"deep label":"","",depth));for(int depth=0;depth<=ContainerLabelProof.MAX_DEPTH;depth++)b.end();yes(b.finish()!=null,"complete deep subtree within budget rejected");
  b=new ContainerLabelProof.Builder();b.begin(node(0,ContainerLabelProof.MAX_NODES-1,"Container",V|ContainerLabelProof.CLICKABLE,"","",0));for(int i=0;i<ContainerLabelProof.MAX_NODES-1;i++){b.begin(node(1,0,"TextView",V,"label","",i));b.end();}b.end();yes(b.finish()!=null,"complete node-budget boundary rejected");
  int metadata=row("","artist").characters;String exact=String.join("",Collections.nCopies(ContainerLabelProof.MAX_CHARACTERS-metadata,"x"));yes(row(exact,"artist")!=null,"full character-budget boundary rejected");yes(row(exact+"x","artist")==null,"character overflow accepted");
  b=new ContainerLabelProof.Builder();b.begin(node(0,1,"ViewGroup",V|ContainerLabelProof.CLICKABLE,"","",0));b.begin(node(1,0,"TextView",V,"first","",0));b.end();b.end();ContainerLabelProof.Proof one=b.finish();yes(one!=null&&b.finish()==null,"builder digest reused");
  System.out.println("ContainerLabelProofTest: "+checks+" checks passed");
 }
}
